/**
 * api-key.spec.ts —— API Key 单测
 */
import { describe, expect, it } from 'vitest'
import { generateApiKey, hashApiKey, verifyApiKey, getKeyPrefix } from './api-key'

describe('API Key 生成与验证', () => {
  describe('generateApiKey', () => {
    it('生成的 Key 有正确前缀', () => {
      const key = generateApiKey()
      expect(key.startsWith('os_sk_')).toBe(true)
    })

    it('每次生成的 Key 不同', () => {
      const k1 = generateApiKey()
      const k2 = generateApiKey()
      expect(k1).not.toBe(k2)
    })

    it('Key 长度符合预期', () => {
      const key = generateApiKey()
      // prefix (6) + 24 bytes hex (48) = 54
      expect(key.length).toBe(6 + 48)
    })
  })

  describe('hashApiKey', () => {
    it('相同输入产生相同 hash', () => {
      const key = 'test-key-123'
      const h1 = hashApiKey(key)
      const h2 = hashApiKey(key)
      expect(h1).toBe(h2)
      expect(h1.length).toBe(64) // SHA-256 hex
    })

    it('不同输入产生不同 hash', () => {
      const h1 = hashApiKey('key-a')
      const h2 = hashApiKey('key-b')
      expect(h1).not.toBe(h2)
    })
  })

  describe('verifyApiKey', () => {
    it('正确的 Key 验证通过', () => {
      const key = generateApiKey()
      const hash = hashApiKey(key)
      expect(verifyApiKey(key, hash)).toBe(true)
    })

    it('错误的 Key 验证不通过', () => {
      const key = generateApiKey()
      const hash = hashApiKey(key)
      expect(verifyApiKey('wrong-key', hash)).toBe(false)
    })
  })

  describe('getKeyPrefix', () => {
    it('正确提取前缀', () => {
      const key = 'os_sk_abcdef1234567890'
      expect(getKeyPrefix(key)).toBe('os_sk_abcd...')
    })
  })
})
